import { describe, expect, it } from 'vitest';
import { HUBSPOT_ACCESS_TOKEN, PRIVATE_APP_ACCESS_TOKEN, resolveAccessTokenKey, } from '../../serverless/constants.js';
describe('resolveAccessTokenKey', () => {
    it('returns the new key for 2027.03', () => {
        expect(resolveAccessTokenKey('2027.03')).toBe(HUBSPOT_ACCESS_TOKEN);
    });
    it('returns the new key for 2027.03-beta', () => {
        expect(resolveAccessTokenKey('2027.03-beta')).toBe(HUBSPOT_ACCESS_TOKEN);
    });
    it('returns the new key for the unstable sentinel', () => {
        expect(resolveAccessTokenKey('unstable')).toBe(HUBSPOT_ACCESS_TOKEN);
    });
    it('returns the legacy key for 2026.09', () => {
        expect(resolveAccessTokenKey('2026.09')).toBe(PRIVATE_APP_ACCESS_TOKEN);
    });
    it('returns the legacy key for 2026.09-beta', () => {
        expect(resolveAccessTokenKey('2026.09-beta')).toBe(PRIVATE_APP_ACCESS_TOKEN);
    });
    it('returns the legacy key for 2025.2', () => {
        expect(resolveAccessTokenKey('2025.2')).toBe(PRIVATE_APP_ACCESS_TOKEN);
    });
    it('returns the legacy key for the testing sentinel', () => {
        expect(resolveAccessTokenKey('testing')).toBe(PRIVATE_APP_ACCESS_TOKEN);
    });
    it('returns the legacy key for the breeze-unstable sentinel', () => {
        expect(resolveAccessTokenKey('breeze-unstable')).toBe(PRIVATE_APP_ACCESS_TOKEN);
    });
});
